  fun queryItems(): List<Pair<String, String>> {
    val items = mutableListOf<Pair<String, String>>()
    questions?.let { items.add("questions" to it.toString()) }
    cards?.let { items.add("cards" to it.toString()) }
    followups?.let { items.add("followups" to it.toString()) }
    calendar?.let { items.add("calendar" to it.toString()) }
    return items
  }
}

